#!/usr/bin/env node
// Generated by ai-factory. Codex post-run path-scope check (the version-independent
// analog of Claude Code's PreToolUse guard). Reads factory-scope.json next to this
// file: { "forbidden": [globs], "agents": { "<agent>": [allow globs] } }.
//
// Usage: git diff --name-only <snapshot> | node factory-check.mjs <agentName>
//   stdin  = newline-separated repo-relative paths the agent changed
//   stdout = the subset that VIOLATES scope (so the orchestrator can revert them)
//   exit 0 = all in scope; exit 1 = at least one violation
//
// Rules (same semantics as the Claude guard):
//   - a path matching any `forbidden` glob (full path OR basename) is a violation
//   - if <agentName> has an allow-list, a path matching none of it is a violation
//   - an agent with no allow-list in the config is not scope-checked (only forbidden applies)
// Do not hand-edit — edit .factory.yaml and re-run `factory install`.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
let config = { forbidden: [], agents: {} };
try { config = JSON.parse(readFileSync(join(here, "factory-scope.json"), "utf8")); } catch {}

function globToRegExp(glob) {
  let re = "";
  let inBrace = false;
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === "*") {
      if (glob[i + 1] === "*") {
        re += ".*";
        i++;
        if (glob[i + 1] === "/") i++;
      } else {
        re += "[^/]*";
      }
    } else if (c === "?") {
      re += "[^/]";
    } else if (c === "{") {
      re += "(";
      inBrace = true;
    } else if (c === "}") {
      re += ")";
      inBrace = false;
    } else if (c === "," && inBrace) {
      re += "|";
    } else if (".+^$()|[]\\".includes(c)) {
      re += "\\" + c;
    } else {
      re += c;
    }
  }
  return new RegExp("^" + re + "$");
}

const agentName = process.argv[2] || "";
const forbidden = (config.forbidden || []).map((g) => ({ g, re: globToRegExp(g) }));
const allowGlobs = agentName && config.agents && config.agents[agentName] ? config.agents[agentName] : null;
const allow = allowGlobs ? allowGlobs.map((g) => ({ g, re: globToRegExp(g) })) : null;

let raw = "";
try { raw = readFileSync(0, "utf8"); } catch {}
const paths = raw.split("\n").map((p) => p.trim()).filter(Boolean);

const violations = [];
for (const rel of paths) {
  // git already gives repo-relative, forward-slash paths.
  const norm = rel.replace(/^[.][/]/, "").replace(/^[/]+/, "");
  const base = norm.split("/").pop() || norm;
  if (forbidden.some((f) => f.re.test(norm) || f.re.test(base))) {
    violations.push(norm);
    continue;
  }
  if (allow !== null && !allow.some((a) => a.re.test(norm))) {
    violations.push(norm);
  }
}

if (violations.length > 0) {
  for (const v of violations) console.log(v); // stdout: machine-readable list to revert
  const label = allow ? `${agentName}'s allowed paths` : "the forbidden list";
  console.error(
    `ai-factory scope check: ${violations.length} file(s) edited outside ${label}:\n` +
      violations.map((v) => "  - " + v).join("\n") +
      `\n(See AGENTS.md -> "Path scoping for agents". Edit .factory.yaml and re-run factory install if intentional.)`,
  );
  process.exit(1);
}
process.exit(0);
